import { useState, useEffect } from 'react';
import { getAllUsers } from '../apis/adminApi';
import { useNavigate } from 'react-router-dom';

function Skeleton({ w='100%', h=16, radius=6, style={} }) {
  return <div style={{ width:w, height:h, borderRadius:radius, background:'linear-gradient(90deg,var(--skeleton-a,#E2E8F0) 25%,var(--skeleton-b,#F1F5F9) 50%,var(--skeleton-a,#E2E8F0) 75%)', backgroundSize:'200% 100%', animation:'shimmer 1.4s infinite', ...style }}/>;
}

const COLORS = ['#6C63FF','#FF6584','#43E97B','#FA8231','#E74C3C','#3498DB','#9B59B6','#1ABC9C','#E67E22','#2ECC71'];
function getInitials(name) { if (!name) return '?'; return name.split(' ').map(w=>w[0]).join('').toUpperCase().slice(0,2); }

// Backend GET /api/admin/auth/users response shape:
// { success, total, verified, pending,
//   users: [{ _id, name, email, mobile, kycVerified, createdAt, role }] }
//
// kycVerified: true  → KYC done, wallet activated
// kycVerified: false → KYC not yet approved (could be any stage)
//
// Bank details: /api/bank/all-banks uses user-level auth only and returns the
// calling user's own banks. An admin bank endpoint is required to show bank
// details per user. Until then, the bank section shows a placeholder.
// TODO (backend team): Add GET /api/admin/bank/all-banks with adminAuth middleware.

function kycLabel(verified) {
  return verified ? 'Verified' : 'Pending';
}
function kycBadgeClass(verified) {
  return verified ? 'b-approved' : 'b-pending';
}

function UserModal({ u, onClose }) {
  if (!u) return null;
  return (
    <div className="overlay" onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div className="modal" style={{ maxWidth:520 }}>
        <div className="modal-head">
          <h3>User Profile</h3>
          <button className="btn btn-ghost icon-btn" onClick={onClose}>
            <svg width="15" height="15" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>
        <div className="modal-body">
          {/* Avatar + name */}
          <div style={{ textAlign:'center', marginBottom:24 }}>
            <div style={{ width:74, height:74, borderRadius:20, background:u.color, display:'flex', alignItems:'center', justifyContent:'center', fontSize:26, fontWeight:700, color:'#fff', margin:'0 auto 12px', boxShadow:`0 6px 20px ${u.color}44` }}>{u.initials}</div>
            <div style={{ fontFamily:"'Space Grotesk',sans-serif", fontSize:21, fontWeight:800, color:'var(--navy)' }}>{u.name || 'Unknown'}</div>
            <div style={{ fontSize:13, color:'var(--gray-400)', marginTop:3 }}>{String(u._id).slice(-12)}</div>
            <div style={{ marginTop:9 }}>
              <span className={`badge ${kycBadgeClass(u.kycVerified)}`}>{kycLabel(u.kycVerified)}</span>
            </div>
          </div>

          {/* Personal details — fields from GET /api/admin/auth/users */}
          <div style={{ marginBottom:20 }}>
            <div style={{ fontSize:10.5, fontWeight:700, color:'var(--gray-400)', textTransform:'uppercase', letterSpacing:'0.8px', marginBottom:10, display:'flex', alignItems:'center', gap:7 }}>
              <div style={{ width:22, height:22, borderRadius:6, background:'#EFF6FF', display:'flex', alignItems:'center', justifyContent:'center', fontSize:12 }}>👤</div>
              Personal Details
            </div>
            <div className="detail-grid">
              {[
                ['Full Name',   u.name    || '—'],
                ['Email',       u.email   || '—'],
                ['Mobile',      u.mobile  || '—'],
                ['Role',        u.role    || 'user'],
                ['KYC Status',  kycLabel(u.kycVerified)],
                ['Joined',      u.createdAt ? new Date(u.createdAt).toLocaleDateString('en-IN', { day:'2-digit', month:'short', year:'numeric' }) : '—'],
              ].map(([l,v])=>(
                <div className="detail-item" key={l}><label>{l}</label><span>{v}</span></div>
              ))}
            </div>
          </div>

          {/* Bank Details — placeholder until backend adds admin bank endpoint */}
          <div>
            <div style={{ fontSize:10.5, fontWeight:700, color:'var(--gray-400)', textTransform:'uppercase', letterSpacing:'0.8px', marginBottom:10, display:'flex', alignItems:'center', gap:7 }}>
              <div style={{ width:22, height:22, borderRadius:6, background:'#FFFBEB', display:'flex', alignItems:'center', justifyContent:'center', fontSize:12 }}>🏦</div>
              Bank Details
            </div>
            <div style={{ background:'#FFFBEB', border:'1.5px dashed #FDE68A', borderRadius:12, padding:'16px 18px', display:'flex', flexDirection:'column', alignItems:'center', gap:6, textAlign:'center' }}>
              <div style={{ fontSize:22 }}>🏦</div>
              <div style={{ fontSize:13, fontWeight:700, color:'#92400E' }}>Admin Bank Endpoint Pending</div>
              <div style={{ fontSize:12, color:'#B45309', lineHeight:1.5 }}>
                The current bank API <code style={{ background:'#FEF3C7', padding:'1px 5px', borderRadius:4 }}>/api/bank/all-banks</code> is user-scoped and cannot return all users' banks from the admin portal.
              </div>
              <div style={{ fontSize:11.5, color:'#78350F', marginTop:4, background:'#FEF9C3', borderRadius:8, padding:'6px 12px' }}>
                ⚙️ Backend team: add <code>GET /api/admin/bank/all-banks</code> with <code>adminAuth</code> middleware and <code>Bank.find({"{}"}).populate("userId","name mobile email")</code>
              </div>
            </div>
          </div>
        </div>
        <div className="modal-foot">
          <button className="btn btn-outline" onClick={onClose}>Close</button>
        </div>
      </div>
    </div>
  );
}

export default function Users() {
  // Backend response: { success, total, verified, pending, users: [...] }
  const [users, setUsers]       = useState([]);
  const [totals, setTotals]     = useState({ total:0, verified:0, pending:0 });
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState('');
  const [search, setSearch]     = useState('');
  const [fKYC, setFKYC]         = useState('All');
  const [sel, setSel]           = useState(null);
  const [page, setPage]         = useState(1);
  const navigate = useNavigate();
  const per = 8;

  useEffect(() => {
    // GET /api/admin/auth/users
    getAllUsers()
      .then(res => {
        // Backend returns: { success, total, verified, pending, users: [...] }
        const arr = res.data?.users || [];
        setTotals({
          total:    res.data?.total    || arr.length,
          verified: res.data?.verified || 0,
          pending:  res.data?.pending  || 0,
        });
        const enriched = arr.map((u, idx) => ({
          ...u,
          initials: getInitials(u.name),
          color:    COLORS[idx % COLORS.length],
        }));
        setUsers(enriched);
      })
      .catch(err => setError(err.response?.data?.message || 'Failed to load users'))
      .finally(() => setLoading(false));
  }, []);

  const filtered = users.filter(u => {
    // fKYC filter based on kycVerified boolean from backend
    const mk = fKYC === 'All'
      || (fKYC === 'Verified' && u.kycVerified === true)
      || (fKYC === 'Pending'  && u.kycVerified === false);
    const q = search.toLowerCase();
    const ms = !search
      || (u.name   || '').toLowerCase().includes(q)
      || (u.email  || '').toLowerCase().includes(q)
      || (u.mobile || '').toLowerCase().includes(q)
      || String(u._id).toLowerCase().includes(q);
    return mk && ms;
  });

  const tp    = Math.max(1, Math.ceil(filtered.length / per));
  const paged = filtered.slice((page-1)*per, page*per);

  return (
    <div className="page">
      <style>{`@keyframes shimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}`}</style>
      <div className="page-header">
        <div className="page-header-left">
          <h2>Users</h2>
          <p>All registered PayO users. KYC status reflects wallet activation.</p>
        </div>
        {/* Stat pills — populated from backend totals directly */}
        <div style={{ display:'flex', gap:10 }}>
          {[
            { label:'Total',    val: totals.total,    color:'#2563EB', bg:'#EFF6FF' },
            { label:'Verified', val: totals.verified, color:'#059669', bg:'#F0FDF4' },
            { label:'Pending',  val: totals.pending,  color:'#D97706', bg:'#FFFBEB' },
          ].map(s => (
            <div key={s.label} style={{ background:s.bg, border:`1.5px solid ${s.color}33`, borderRadius:10, padding:'9px 16px', textAlign:'center', minWidth:70 }}>
              <div style={{ fontFamily:"'Space Grotesk',sans-serif", fontSize:18, fontWeight:800, color:s.color }}>{loading ? '—' : s.val.toLocaleString()}</div>
              <div style={{ fontSize:11, color:s.color, fontWeight:600, opacity:0.8 }}>{s.label}</div>
            </div>
          ))}
        </div>
      </div>

      {error && (
        <div style={{ background:'#FEF2F2', border:'1px solid #FECACA', borderRadius:10, padding:'12px 16px', marginBottom:18, color:'#DC2626', fontSize:13 }}>
          ⚠️ {error}
        </div>
      )}

      <div className="card">
        <div className="filter-bar">
          <div className="search-field">
            <svg width="14" height="14" fill="none" stroke="var(--gray-400)" strokeWidth="2" viewBox="0 0 24 24"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
            <input
              placeholder="Search by name, email, mobile or ID..."
              value={search}
              onChange={e=>{ setSearch(e.target.value); setPage(1); }}
            />
          </div>
          {/* Filter by kycVerified: backend gives boolean, we map to Verified/Pending */}
          <select className="filter-select" value={fKYC} onChange={e=>{ setFKYC(e.target.value); setPage(1); }}>
            <option value="All">All Users</option>
            <option value="Verified">KYC Verified</option>
            <option value="Pending">KYC Pending</option>
          </select>
          <div className="filter-count">{loading ? '—' : `${filtered.length} users`}</div>
        </div>

        <div className="table-wrap">
          <table>
            <thead>
              <tr>
                <th>User</th>
                <th>Email</th>
                <th>Mobile</th>
                <th>KYC Status</th>
                <th>Joined</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading
                ? Array(6).fill(0).map((_,i) => (
                    <tr key={i}>
                      <td><div style={{ display:'flex', alignItems:'center', gap:10 }}><Skeleton w={34} h={34} radius={8}/><div><Skeleton w={100} h={12} radius={4} style={{ marginBottom:4 }}/><Skeleton w={70} h={10} radius={4}/></div></div></td>
                      <td><Skeleton w={140} h={12} radius={4}/></td>
                      <td><Skeleton w={100} h={12} radius={4}/></td>
                      <td><Skeleton w={70} h={22} radius={20}/></td>
                      <td><Skeleton w={80} h={12} radius={4}/></td>
                      <td><Skeleton w={60} h={28} radius={8}/></td>
                    </tr>
                  ))
                : paged.map(u => (
                    <tr key={u._id}>
                      <td>
                        <div className="user-cell">
                          <div className="avatar" style={{ background:u.color }}>{u.initials}</div>
                          <div>
                            <div className="uname">{u.name || '—'}</div>
                            {/* Show last 10 chars of MongoDB _id as short ID */}
                            <div className="uid">{String(u._id).slice(-10)}</div>
                          </div>
                        </div>
                      </td>
                      <td style={{ fontSize:13, color:'var(--gray-600)' }}>{u.email || '—'}</td>
                      <td style={{ fontSize:13, color:'var(--gray-600)' }}>{u.mobile || '—'}</td>
                      {/* kycVerified: backend Boolean — true = wallet activated */}
                      <td>
                        <span className={`badge ${kycBadgeClass(u.kycVerified)}`}>
                          {kycLabel(u.kycVerified)}
                        </span>
                      </td>
                      <td style={{ fontSize:13, color:'var(--gray-400)' }}>
                        {u.createdAt ? new Date(u.createdAt).toLocaleDateString('en-IN', { day:'2-digit', month:'short', year:'numeric' }) : '—'}
                      </td>
                      <td>
                        <div className="act-group">
                          <button
                            className="btn btn-outline"
                            style={{ fontSize:12, padding:'5px 11px' }}
                            onClick={() => setSel(u)}>
                            View
                          </button>
                          {/* If KYC not verified, link to KYC Review page */}
                          {!u.kycVerified && (
                            <button
                              className="btn btn-outline"
                              style={{ fontSize:12, padding:'5px 11px', color:'#D97706', borderColor:'#FDE68A' }}
                              onClick={() => navigate('/kyc')}>
                              KYC
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))
              }
            </tbody>
          </table>
          {!loading && paged.length === 0 && (
            <div className="empty">No users found matching your filters.</div>
          )}
        </div>

        {!loading && filtered.length > 0 && (
          <div className="pagination">
            <div className="pag-info">
              Showing {Math.min((page-1)*per+1, filtered.length)}–{Math.min(page*per, filtered.length)} of {filtered.length}
            </div>
            <div className="pag-btns">
              <button className="pag-btn" disabled={page===1} onClick={()=>setPage(p=>p-1)}>‹</button>
              {Array.from({ length:tp }, (_,i) => (
                <button key={i+1} className={`pag-btn${page===i+1?' act':''}`} onClick={()=>setPage(i+1)}>{i+1}</button>
              ))}
              <button className="pag-btn" disabled={page===tp} onClick={()=>setPage(p=>p+1)}>›</button>
            </div>
          </div>
        )}
      </div>

      {sel && <UserModal u={sel} onClose={()=>setSel(null)} />}
    </div>
  );
}
